/* GL object state and programmable draw adapter. Included by gles.c. */
static void gen_objects(unsigned k,GLsizei n,GLuint *out){BEGIN_VOID;if(n<0||(!out&&n))vex_gl_error(GL_INVALID_VALUE);else for(GLsizei i=0;i<n;++i){gl_object *o=allocate(c->share,k);if(!o){vex_gl_error(GL_OUT_OF_MEMORY);break;}out[i]=o->name;}END;}
void glGenBuffers(GLsizei n,GLuint *v){gen_objects(OBJ_BUFFER,n,v);}void glGenTextures(GLsizei n,GLuint *v){gen_objects(OBJ_TEXTURE,n,v);}void glGenRenderbuffers(GLsizei n,GLuint *v){gen_objects(OBJ_RENDERBUFFER,n,v);}void glGenFramebuffers(GLsizei n,GLuint *v){gen_objects(OBJ_FRAMEBUFFER,n,v);}
static void delete_objects(unsigned kind,GLsizei n,const GLuint *names){BEGIN_VOID;if(n<0||(!names&&n))vex_gl_error(GL_INVALID_VALUE);else for(GLsizei i=0;i<n;++i){gl_object *o=lookup(c->share,names[i],kind);if(!o)continue;o->deleted=1;
    if(kind==OBJ_BUFFER){if(c->array_buffer==o)binding(&c->array_buffer,NULL);if(c->elements==o)binding(&c->elements,NULL);for(unsigned a=0;a<8;++a)if(c->attrib[a].buffer==o)binding(&c->attrib[a].buffer,NULL);}
    if(kind==OBJ_TEXTURE)for(unsigned a=0;a<16;++a)if(c->texture[a]==o)binding(&c->texture[a],NULL);
    if(kind==OBJ_FRAMEBUFFER&&c->framebuffer==o)binding(&c->framebuffer,NULL);if(kind==OBJ_RENDERBUFFER&&c->renderbuffer==o)binding(&c->renderbuffer,NULL);
    if((kind==OBJ_TEXTURE||kind==OBJ_RENDERBUFFER)&&c->framebuffer){gl_object *f=c->framebuffer;if(f->u.framebuffer.color==o)binding(&f->u.framebuffer.color,NULL);if(f->u.framebuffer.depth==o)binding(&f->u.framebuffer.depth,NULL);if(f->u.framebuffer.stencil==o)binding(&f->u.framebuffer.stencil,NULL);}
    vex_gl_object_release(o);}END;}
void glDeleteBuffers(GLsizei n,const GLuint *p){delete_objects(OBJ_BUFFER,n,p);}void glDeleteTextures(GLsizei n,const GLuint *p){delete_objects(OBJ_TEXTURE,n,p);}void glDeleteRenderbuffers(GLsizei n,const GLuint *p){delete_objects(OBJ_RENDERBUFFER,n,p);}void glDeleteFramebuffers(GLsizei n,const GLuint *p){delete_objects(OBJ_FRAMEBUFFER,n,p);}
static GLboolean is_object(unsigned k,GLuint id){BEGIN_RET(0);gl_object *o=lookup(c->share,id,k);GLboolean r=o&&o->instantiated;END;return r;}
GLboolean glIsBuffer(GLuint id){return is_object(OBJ_BUFFER,id);}GLboolean glIsTexture(GLuint id){return is_object(OBJ_TEXTURE,id);}GLboolean glIsFramebuffer(GLuint id){return is_object(OBJ_FRAMEBUFFER,id);}GLboolean glIsRenderbuffer(GLuint id){return is_object(OBJ_RENDERBUFFER,id);}
static gl_object *bind_name(egl_context *c,GLuint id,unsigned k){gl_object *o=lookup(c->share,id,k);if(!o&&id)vex_gl_error(GL_INVALID_VALUE);if(o)o->instantiated=1;return o;}
void glBindBuffer(GLenum target,GLuint id){BEGIN_VOID;if(target!=GL_ARRAY_BUFFER&&target!=GL_ELEMENT_ARRAY_BUFFER)vex_gl_error(GL_INVALID_ENUM);else {gl_object *o=bind_name(c,id,OBJ_BUFFER);if(!id||o)binding(target==GL_ARRAY_BUFFER?&c->array_buffer:&c->elements,o);}END;}
static gl_object *buffer_target(egl_context *c,GLenum t){if(t==GL_ARRAY_BUFFER)return c->array_buffer;if(t==GL_ELEMENT_ARRAY_BUFFER)return c->elements;vex_gl_error(GL_INVALID_ENUM);return NULL;}
void glBufferData(GLenum t,GLsizeiptr bytes,const void *data,GLenum usage){BEGIN_VOID;gl_object *o=buffer_target(c,t);if(bytes<0)vex_gl_error(GL_INVALID_VALUE);else if(usage!=GL_STATIC_DRAW&&usage!=GL_DYNAMIC_DRAW&&usage!=GL_STREAM_DRAW)vex_gl_error(GL_INVALID_ENUM);else if(!o)vex_gl_error(GL_INVALID_OPERATION);else {void *p=bytes?calloc(1,bytes):NULL;if(bytes&&!p)vex_gl_error(GL_OUT_OF_MEMORY);else {if(data)memcpy(p,data,bytes);free(o->u.buffer.bytes);o->u.buffer.bytes=p;o->u.buffer.size=bytes;o->u.buffer.usage=usage;}}END;}
void glBufferSubData(GLenum t,GLintptr offset,GLsizeiptr bytes,const void *data){BEGIN_VOID;gl_object *o=buffer_target(c,t);if(offset<0||bytes<0||(!data&&bytes))vex_gl_error(GL_INVALID_VALUE);else if(!o)vex_gl_error(GL_INVALID_OPERATION);else if((size_t)offset>o->u.buffer.size||(size_t)bytes>o->u.buffer.size-offset)vex_gl_error(GL_INVALID_VALUE);else if(bytes)memcpy(o->u.buffer.bytes+offset,data,bytes);END;}
void glGetBufferParameteriv(GLenum t,GLenum n,GLint *v){BEGIN_VOID;gl_object *o=buffer_target(c,t);if(!o||!v)vex_gl_error(GL_INVALID_OPERATION);else if(n==GL_BUFFER_SIZE)*v=o->u.buffer.size;else if(n==GL_BUFFER_USAGE)*v=o->u.buffer.usage;else vex_gl_error(GL_INVALID_ENUM);END;}
void glActiveTexture(GLenum u){BEGIN_VOID;if(u<GL_TEXTURE0||u>=GL_TEXTURE0+16)vex_gl_error(GL_INVALID_ENUM);else c->active_texture=u-GL_TEXTURE0;END;}
void glBindTexture(GLenum t,GLuint id){BEGIN_VOID;if(t!=GL_TEXTURE_2D)vex_gl_error(GL_INVALID_ENUM);else {gl_object *o=bind_name(c,id,OBJ_TEXTURE);if(!id||o)binding(&c->texture[c->active_texture],o);}END;}
static size_t pixel_components(GLenum f){return f==GL_RGBA?4:f==GL_RGB?3:f==GL_ALPHA||f==GL_LUMINANCE?1:f==GL_LUMINANCE_ALPHA?2:0;}
static uint32_t unpack_pixel(const uint8_t *p,GLenum f){uint32_t r,g,b,a;if(f==GL_RGBA){r=p[0];g=p[1];b=p[2];a=p[3];}else if(f==GL_RGB){r=p[0];g=p[1];b=p[2];a=255;}else if(f==GL_ALPHA){r=g=b=0;a=p[0];}else {r=g=b=p[0];a=f==GL_LUMINANCE_ALPHA?p[1]:255;}return r|(g<<8)|(b<<16)|(a<<24);}
void glPixelStorei(GLenum p,GLint v){BEGIN_VOID;if(p!=GL_PACK_ALIGNMENT&&p!=GL_UNPACK_ALIGNMENT)vex_gl_error(GL_INVALID_ENUM);else if(v!=1&&v!=2&&v!=4&&v!=8)vex_gl_error(GL_INVALID_VALUE);else if(p==GL_PACK_ALIGNMENT)c->pack=v;else c->unpack=v;END;}
void glTexImage2D(GLenum t,GLint level,GLint internal,GLsizei w,GLsizei h,GLint border,GLenum format,GLenum type,const void *pixels){BEGIN_VOID;gl_object *o=c->texture[c->active_texture];size_t components=pixel_components(format);
    if(t!=GL_TEXTURE_2D||!components||type!=GL_UNSIGNED_BYTE)vex_gl_error(GL_INVALID_ENUM);else if(level!=0||border||w<0||h<0||w>4096||h>4096)vex_gl_error(GL_INVALID_VALUE);else if(internal!=(GLint)format||!o)vex_gl_error(GL_INVALID_OPERATION);else {uint32_t *dst=w&&h?calloc((size_t)w*h,4):NULL;if(w&&h&&!dst)vex_gl_error(GL_OUT_OF_MEMORY);else {size_t pitch=((size_t)w*components+c->unpack-1)&~(size_t)(c->unpack-1);if(pixels)for(int y=0;y<h;++y)for(int x=0;x<w;++x)dst[(size_t)y*w+x]=unpack_pixel((const uint8_t*)pixels+y*pitch+x*components,format);free(o->u.texture.pixels);o->u.texture.pixels=dst;o->u.texture.width=w;o->u.texture.height=h;o->u.texture.format=format;}}END;}
void glTexSubImage2D(GLenum t,GLint level,GLint x,GLint y,GLsizei w,GLsizei h,GLenum f,GLenum type,const void *pixels){BEGIN_VOID;gl_object *o=c->texture[c->active_texture];size_t n=pixel_components(f);
    if(t!=GL_TEXTURE_2D||!n||type!=GL_UNSIGNED_BYTE)vex_gl_error(GL_INVALID_ENUM);else if(level||x<0||y<0||w<0||h<0||(!pixels&&w&&h))vex_gl_error(GL_INVALID_VALUE);else if(!o||!o->u.texture.pixels)vex_gl_error(GL_INVALID_OPERATION);else if(f!=o->u.texture.format)vex_gl_error(GL_INVALID_OPERATION);else if(x>o->u.texture.width||w>o->u.texture.width-x||y>o->u.texture.height||h>o->u.texture.height-y)vex_gl_error(GL_INVALID_VALUE);else {size_t pitch=((size_t)w*n+c->unpack-1)&~(size_t)(c->unpack-1);for(int j=0;j<h;++j)for(int i=0;i<w;++i)o->u.texture.pixels[(size_t)(j+y)*o->u.texture.width+i+x]=unpack_pixel((const uint8_t*)pixels+j*pitch+i*n,f);}END;}
void glTexParameteri(GLenum t,GLenum p,GLint v){BEGIN_VOID;gl_object *o=c->texture[c->active_texture];if(t!=GL_TEXTURE_2D)vex_gl_error(GL_INVALID_ENUM);else if(!o)vex_gl_error(GL_INVALID_OPERATION);else if(p==GL_TEXTURE_MIN_FILTER||p==GL_TEXTURE_MAG_FILTER){if(v!=GL_LINEAR&&v!=GL_NEAREST)vex_gl_error(GL_INVALID_ENUM);else if(p==GL_TEXTURE_MIN_FILTER)o->u.texture.min=v;else o->u.texture.mag=v;}else if(p==GL_TEXTURE_WRAP_S||p==GL_TEXTURE_WRAP_T){if(v!=GL_REPEAT&&v!=GL_CLAMP_TO_EDGE&&v!=GL_MIRRORED_REPEAT)vex_gl_error(GL_INVALID_ENUM);else if(p==GL_TEXTURE_WRAP_S)o->u.texture.u=v;else o->u.texture.v=v;}else vex_gl_error(GL_INVALID_ENUM);END;}
void glTexParameterf(GLenum t,GLenum p,GLfloat v){glTexParameteri(t,p,(GLint)v);}
void glGetTexParameteriv(GLenum t,GLenum p,GLint *out){BEGIN_VOID;gl_object *o=c->texture[c->active_texture];if(t!=GL_TEXTURE_2D)vex_gl_error(GL_INVALID_ENUM);else if(!o||!out)vex_gl_error(GL_INVALID_OPERATION);else if(p==GL_TEXTURE_MIN_FILTER)*out=o->u.texture.min;else if(p==GL_TEXTURE_MAG_FILTER)*out=o->u.texture.mag;else if(p==GL_TEXTURE_WRAP_S)*out=o->u.texture.u;else if(p==GL_TEXTURE_WRAP_T)*out=o->u.texture.v;else vex_gl_error(GL_INVALID_ENUM);END;}
void glGenerateMipmap(GLenum t){BEGIN_VOID;(void)t;vex_gl_error(GL_INVALID_OPERATION);END;}
#include "gles_program.h"
#include "gles_draw.h"
